package vn.hust.restaurant.service;
import java.math.*;import java.sql.*;import java.util.*;import vn.hust.restaurant.config.AppConfig;import vn.hust.restaurant.model.*;import vn.hust.restaurant.repository.*;
public class PaymentService{private final OrderRepository orders;private final PromotionRepository promos;private final PaymentRepository repo;public PaymentService(OrderRepository o,PromotionRepository p,PaymentRepository r){orders=o;promos=p;repo=r;}public List<Promotion>promotions()throws SQLException{return promos.active();}
 public InvoicePreview preview(OrderSummary order,Integer customer,Promotion promo,int points)throws SQLException{List<OrderItemView>items=orders.items(order.id()).stream().filter(x->!"DA_HUY".equals(x.kitchenStatus())).toList();if(items.isEmpty())throw new IllegalArgumentException("Order chưa có món");BigDecimal sub=items.stream().map(OrderItemView::lineTotal).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal discount=discount(promo,sub,items);int available=repo.customerPoints(customer);int used=Math.max(0,Math.min(points,available));BigDecimal pointValue=AppConfig.appDecimal("point.redeem.value","1000");BigDecimal pointDiscount=pointValue.multiply(BigDecimal.valueOf(used));BigDecimal taxable=sub.subtract(discount).max(BigDecimal.ZERO);BigDecimal vat=taxable.multiply(AppConfig.appDecimal("vat.rate","0.08")).setScale(0,RoundingMode.HALF_UP);BigDecimal total=taxable.add(vat).subtract(pointDiscount).max(BigDecimal.ZERO);if(pointDiscount.compareTo(taxable.add(vat))>0){used=taxable.add(vat).divide(pointValue,0,RoundingMode.DOWN).intValue();pointDiscount=pointValue.multiply(BigDecimal.valueOf(used));total=taxable.add(vat).subtract(pointDiscount);}int earned=total.divide(AppConfig.appDecimal("point.earn.amount","10000"),0,RoundingMode.DOWN).intValue();return new InvoicePreview(order.id(),order.code(),order.tableCode(),items,sub,discount,vat,used,pointDiscount,total,earned,customer,promo==null?null:promo.id());}
 private BigDecimal discount(Promotion p,BigDecimal sub,List<OrderItemView>items){if(p==null||sub.compareTo(p.minimumAmount())<0)return BigDecimal.ZERO;BigDecimal d=switch(p.type()){case"PHAN_TRAM"->sub.multiply(p.value()).divide(BigDecimal.valueOf(100));case"SO_TIEN"->p.value();case"MON_PHAN_TRAM"->items.stream().filter(x->Objects.equals(x.menuItemId(),p.targetMenuItemId())).map(x->x.lineTotal().multiply(p.value()).divide(BigDecimal.valueOf(100))).reduce(BigDecimal.ZERO,BigDecimal::add);case"MUA_X_TANG_Y"->items.stream().filter(x->Objects.equals(x.menuItemId(),p.targetMenuItemId())).map(x->{int free=(x.quantity()/(p.buyQuantity()+p.getQuantity()))*p.getQuantity();return x.unitPrice().multiply(BigDecimal.valueOf(free));}).reduce(BigDecimal.ZERO,BigDecimal::add);default->BigDecimal.ZERO;};if(p.maximumDiscount()!=null&&p.maximumDiscount().signum()>0)d=d.min(p.maximumDiscount());return d.min(sub).setScale(0,RoundingMode.HALF_UP);}
 public long pay(InvoicePreview p,int cashier,List<PaymentPart>parts)throws SQLException{return repo.finalizeInvoice(p,cashier,parts);}public Map<String,Object>invoice(long id)throws SQLException{return repo.invoice(id);}}
